METINLER = [
 M('Muhtasarü’l-Kudûrî — Kitâbü’t-tahâre', 'Hanefî fıkıh metinlerinin klasik başlangıcı: abdestin farzları âyetle başlar.',
   'قال اللهُ تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ﴾ ففرضُ الطهارةِ: غَسلُ الأعضاءِ الثلاثةِ، ومسحُ الرأسِ', 'مختصر القدوري، كتاب الطهارة'),
 M('Cüveynî, el-Varakāt — giriş', 'Usûl-i fıkhın en kısa giriş metninin başı: asl, fer‘ ve fıkhın tarifi.',
   'هذه ورقاتٌ تشتملُ على معرفةِ فصولٍ من أصولِ الفقهِ، وذلك مؤلَّفٌ من جزأين مفردين: فالأصلُ ما بُنيَ عليه غيرُه، والفرعُ ما يُبنى على غيره، والفقهُ معرفةُ الأحكامِ الشرعيةِ التي طريقُها الاجتهادُ', 'الجويني، الورقات'),
 M('Beş külli kaide', 'Bütün fıkhın dayandığı söylenen beş temel kaide (İbn Nüceym, el-Eşbâh; Mecelle’nin ilk maddeleri de bunlardır).',
   'الأمورُ بمقاصدِها — اليقينُ لا يزولُ بالشكِّ — المشقةُ تجلبُ التيسيرَ — الضررُ يُزالُ — العادةُ مُحكَّمةٌ', 'ابن نجيم، الأشباه والنظائر، الفن الأول'),
 M('Muâz hadisi — içtihadın delili', 'Muâz b. Cebel’in Yemen’e gönderilirken verdiği cevap; usûl kitaplarında kıyas ve içtihadın delili olarak zikredilir.',
   'كَيْفَ تَقْضِي إِذَا عَرَضَ لَكَ قَضَاءٌ؟ قَالَ: أَقْضِي بِكِتَابِ اللَّهِ، قَالَ: فَإِنْ لَمْ تَجِدْ فِي كِتَابِ اللَّهِ؟ قَالَ: فَبِسُنَّةِ رَسُولِ اللَّهِ، قَالَ: فَإِنْ لَمْ تَجِدْ؟ قَالَ: أَجْتَهِدُ رَأْيِي وَلَا آلُو', 'أبو داود، الأقضية ١١ (٣٥٩٢)؛ الترمذي، الأحكام ٣'),
]

